import fs from 'node:fs';
let s = '';
try { s = fs.readFileSync('summary.txt', 'utf8'); } catch { console.log('FAIL: summary.txt 不存在'); process.exit(1); }
const hanzi = (s.match(/[\u4e00-\u9fff]/g) || []).length;
if (!s.includes('回环验证')) { console.log('FAIL: 缺少术语「回环验证」'); process.exit(1); }
if (hanzi > 80) { console.log('FAIL: 汉字数 ' + hanzi + ' 超过 80'); process.exit(1); }
if (hanzi < 30) { console.log('FAIL: 汉字数 ' + hanzi + ' 少于 30，不像完整摘要'); process.exit(1); }
console.log('OK: 汉字数 ' + hanzi);
